import React from 'react';
import { Link } from 'react-router-dom';

const EmbedChatbot = () => {
    return (
        <div className="doc-article">
            <div className="doc-header">
                <h1>Embed WebVox Bot</h1>
                <p className="doc-subtitle">
                    Learn how to integrate the WebVox widget directly into your React, Vue, or Vanilla JS website.
                </p>
            </div>

            <div className="doc-section">
                <h2>Coming Soon</h2>
                <p>The code snippets and integration details for embedding the bot will be documented here.</p>
            </div>

            <div className="doc-footer-nav">
                <Link to="/docs/setup-hasura" className="nav-prev">
                    <span>&larr; Previous</span>
                    <strong>Setup Hasura</strong>
                </Link>
                <div className="nav-empty"></div>
            </div>
        </div>
    );
};

export default EmbedChatbot;
